public void testGetRepository() throws Exception {
    Object repository = Mockito.spy(AbstractRepository.class);
    Hashtable<String, String> environment = new Hashtable<String, String>();
    environment.put("java.naming.factory.initial", "org.osjava.sj.memory.MemoryContextFactory");
    environment.put("org.osjava.sj.jndi.shared", "true");
    InitialContext context = new InitialContext(environment);
    context.bind("repository", repository);
    // Test lookup with a traditional map of parameters
    Map<String, String> parameters = new HashMap<String, String>();
    parameters.put("org.apache.jackrabbit.repository.jndi.name", "repository");
    parameters.put("java.naming.factory.initial", "org.osjava.sj.memory.MemoryContextFactory");
    parameters.put("org.osjava.sj.jndi.shared", "true");
    assertTrue(repository == JcrUtils.getRepository(parameters));
    // Test lookup with URI query parameters
    assertTrue(repository == JcrUtils.getRepository("jndi://x" + "?org.apache.jackrabbit.repository.jndi.name=repository" + "&org.osjava.sj.jndi.shared=true" + "&java.naming.factory.initial" + "=org.osjava.sj.memory.MemoryContextFactory"));
    // Test lookup with the custom JNDI URI format (JCR-2771)
    assertTrue(repository == JcrUtils.getRepository("jndi://org.osjava.sj.memory.MemoryContextFactory/repository" + "?org.osjava.sj.jndi.shared=true"));
    try {
        JcrUtils.getRepository("jndi://org.osjava.sj.memory.MemoryContextFactory/missing");
        fail("Repository lookup failure should throw an exception");
    } catch (RepositoryException expected) {
    }
}

